import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"캠페인 진행과 위기","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Campaign-Progression.md","filePath":"rules/Campaign-Progression.md"}'),d={name:"rules/Campaign-Progression.md"};function l(n,t,r,h,o,g){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="캠페인-진행과-위기" tabindex="-1">캠페인 진행과 위기 <a class="header-anchor" href="#캠페인-진행과-위기" aria-label="Permalink to &quot;캠페인 진행과 위기&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-campaign-progression.svg?raw=true" alt="캠페인 성장과 위기의 아이소 영향권"></p><p>캠페인 성장 단계와 위기 영향을 영향권과 연결 그래프로 추적합니다.</p><p>진행은 영토 숫자가 아니라 거점의 안정화, 전문화, 연결 투사력과 플레이어가 세운 질서의 정당성으로 측정합니다. 아래 수치는 <strong>설계 가정</strong>입니다.</p><h2 id="입력과-출력" tabindex="-1">입력과 출력 <a class="header-anchor" href="#입력과-출력" aria-label="Permalink to &quot;입력과 출력&quot;">​</a></h2><table tabindex="0"><thead><tr><th>입력</th><th style="text-align:right;">범위·기본값</th><th>출력</th></tr></thead><tbody><tr><td>안보 <code>S_i</code></td><td style="text-align:right;">0~100, 안정 거점 70</td><td>폭력 억제와 방어</td></tr><tr><td>기능 <code>F_i</code></td><td style="text-align:right;">0~100, 안정 거점 70</td><td>시설·생산·피난 서비스</td></tr><tr><td>정통성 <code>L_i</code></td><td style="text-align:right;">0~100, 안정 거점 60</td><td>현지 통치 수용</td></tr><tr><td>연결 <code>K_i</code></td><td style="text-align:right;">0~1</td><td>구호·교역·증원 가능성</td></tr><tr><td>부족 <code>x_i</code></td><td style="text-align:right;">0~1</td><td>회복·산출 감점</td></tr><tr><td>과확장 <code>O</code></td><td style="text-align:right;">0~2</td><td>네트워크 전체 부담</td></tr><tr><td>긴장도 <code>E</code></td><td style="text-align:right;">0~100, 시작 20</td><td>주간 위기 확률과 강도</td></tr></tbody></table><h2 id="계산-규칙" tabindex="-1">계산 규칙 <a class="header-anchor" href="#계산-규칙" aria-label="Permalink to &quot;계산 규칙&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>K_i = clamp(max_path(경로신뢰도), 0, 1)</span></span>
<span class="line"><span>부족_i = 수요가 0이면 0, 아니면 1 - clamp(가용량 / 수요, 0, 1)</span></span>
<span class="line"><span>회복 = clamp(10 + 10*위기해결품질, 0, 20)</span></span>
<span class="line"><span>E&#39; = clamp(E + 시간압력 + 확장충격 + 부족 + 고립 + 과확장 - 회복, 0, 100)</span></span>
<span class="line"><span>위기확률 = clamp(0.10 + 0.01*(E-50) + 0.15*O + 0.10*평균부족 + 0.10*평균고립, 0.10, 0.75)</span></span></code></pre></div><p>과확장 <code>O</code>와 고립은 <a href="/world/Logistics-and-Infrastructure.html">물류와 기반 시설</a>에 정의된 공유 0~2 척도를 그대로 사용하며, <code>평균부족</code>과 <code>평균고립</code>은 거점 가중치 가중 평균(분모 하한 0.25)입니다. 집계에 쓰는 거점 가중치는 <strong>설계 가정</strong>으로 일반 1.0, 환승 1.5(하한 0.25)이며 과확장 척도 자체는 바꾸지 않습니다. 수요가 0인 항목은 <a href="/world/Economy-and-Production.html">경제와 생산</a>의 공유 규칙대로 부족 0으로 처리하고 0으로 나누지 않습니다. <code>회복</code>은 그 주에 위기를 해결했을 때만 적용하며(해결 품질 0~1), 해결이 없으면 0입니다. 위기 종류와 대상은 캠페인 시드, 주차와 전용 난수 흐름으로 결정하며 원인 가중치를 원장에 기록합니다. 계열 가중치는 <strong>설계 가정</strong>으로 부족·오염 <code>1 + 4*평균부족</code>, 고립·정전·경로 탈취 <code>1 + 4*평균고립</code>, 과확장·분열·다면 전선 약탈 <code>1 + 4*min(O, 1)</code>, 외부 충격 <code>1 + E/100</code>이고, 대상 가중치는 <code>거점가중치_i * (1 + 2*부족_i + 2*고립_i + (1 - min(S_i, F_i, L_i) / 100))</code>입니다.</p><h2 id="기본-수치" tabindex="-1">기본 수치 <a class="header-anchor" href="#기본-수치" aria-label="Permalink to &quot;기본 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th style="text-align:right;">기본값</th><th style="text-align:right;">최소</th><th style="text-align:right;">최대</th></tr></thead><tbody><tr><td>캠페인 시작 긴장도</td><td style="text-align:right;">20</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>신규 점령 확장 충격</td><td style="text-align:right;">5</td><td style="text-align:right;">0</td><td style="text-align:right;">10</td></tr><tr><td>부족 임계</td><td style="text-align:right;">0.25</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>심각 부족 임계</td><td style="text-align:right;">0.75</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>강제 대응까지 심각 부족</td><td style="text-align:right;">3일</td><td style="text-align:right;">1일</td><td style="text-align:right;">7일</td></tr><tr><td>붕괴 선택까지 심각 부족</td><td style="text-align:right;">7일</td><td style="text-align:right;">3일</td><td style="text-align:right;">14일</td></tr><tr><td>위기 확률</td><td style="text-align:right;">10%</td><td style="text-align:right;">10%</td><td style="text-align:right;">75%</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[점령] --&gt; B[안정화]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[전문화]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[노선 투사]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E[질서 헌장]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B -. 실패 .-&gt; R[회복 태세]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D -. 과확장 .-&gt; R</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R --&gt; B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt; V[다중 결말 평가]</span></span></code></pre></div><h2 id="경계-상황" tabindex="-1">경계 상황 <a class="header-anchor" href="#경계-상황" aria-label="Permalink to &quot;경계 상황&quot;">​</a></h2><ul><li>심각 부족 3일은 강제 지역 비상사건, 7일은 철수·배급 강제·항복 협상·지역 붕괴 선택을 엽니다.</li><li>고립된 거점은 비축으로 버틸 수 있지만 증인·구호·수리 인력이 오지 않아 회복이 느립니다.</li><li>과확장은 적을 마법처럼 강화하지 않고 모든 거점의 행정·순찰·수리 지연으로 나타납니다.</li><li>같은 주에 여러 위기가 발생하면 전용 난수 결과를 고정한 뒤 위기 ID 순서로 예약합니다.</li><li>승리는 서울 통일 하나가 아니라 노선 연합, 독립 역 협약, 교역 질서, 기술 복구 같은 헌장 조건으로 평가합니다.</li></ul><h2 id="계산-예시" tabindex="-1">계산 예시 <a class="header-anchor" href="#계산-예시" aria-label="Permalink to &quot;계산 예시&quot;">​</a></h2><p>긴장도 58, 과확장 0.5, 평균 부족 0.139, 평균 고립 0.2이면 <code>위기확률=clamp(0.10+0.08+0.075+0.0139+0.02,0.10,0.75)=0.2889</code>, 즉 28.89%입니다. 위기가 해결 품질 0.8로 끝나면 그 주의 회복 항은 <code>회복=clamp(10+10*0.8,0,20)=18</code>입니다. 이 값은 <code>E&#39;</code> 공식에서 차감 항으로만 쓰이며, 같은 주의 시간압력·확장충격·부족·고립·과확장 증가 항이 모두 0일 때만 <code>E&#39;=E-18</code>이 됩니다. 성공적인 회복도 캠페인 진행의 실질적 선택이 됩니다.</p>`,16)])])}const y=a(d,[["render",l]]);export{p as __pageData,y as default};
